const input = $input.all();

const normalizedReviews = [];

for (const item of input) {
  const data = item.json;

  const reviews = data.reviews || [];

  for (const review of reviews) {
    const comment = review.comments?.[0]?.userComment || {};
    const deviceMetadata = comment.deviceMetadata || {};

    normalizedReviews.push({
      json: {
        review_id: review.reviewId || '',
        author_name: review.authorName || '',

        // Review details
        review_text: comment.text || '',
        rating: Number(comment.starRating || 0),

        // App details
        app_version_code: comment.appVersionCode || '',
        app_version_name: comment.appVersionName || '',

        // Date
        review_submit_date: comment.reviewSubmitDate || '',
        review_last_update_date: comment.reviewLastUpdateDate || '',

        // Device details
        device: comment.device || '',
        os_version: comment.androidOsVersion || '',

        // Device metadata
        product_name: deviceMetadata.productName || '',
        manufacturer: deviceMetadata.manufacturer || '',

        // Language
        language_code: comment.originalText?.languageCode || '',

        // Original review text
        original_text: comment.originalText?.text || '',

        // Source
        platform: review.reviewId?.startsWith('gp:')
          ? 'Google Play'
          : review.reviewId?.startsWith('apple:')
            ? 'Apple App Store'
            : 'Unknown',

        processed_at: new Date().toISOString()
      }
    });
  }
}

return normalizedReviews;

const items = $input.all();

return items.map((item) => {
  const text = item.json?.content?.parts?.[0]?.text;

  if (!text) {
    return {
      json: {
        success: false,
        error: "Gemini response text not found",
        original: item.json
      }
    };
  }

  try {
    // Remove markdown code fences if Gemini returns ```json ... ```
    const cleanText = text
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();

    const parsed = JSON.parse(cleanText);

    return {
      json: {
        success: true,
        ...parsed
      }
    };

  } catch (error) {
    return {
      json: {
        success: false,
        error: "Unable to parse Gemini JSON",
        errorMessage: error.message,
        rawText: text
      }
    };
  }
});

const output = [];

for (const item of $input.all()) {
  try {
    const text = item.json.content?.parts?.[0]?.text;

    if (!text) {
      output.push({
        json: {
          success: false,
          error: "Text field not found"
        }
      });

      continue;
    }

    // Convert Gemini text JSON string into JavaScript object
    const parsed = JSON.parse(text);

    output.push({
      json: {
        category: parsed.category,
        category_confidence: parsed.category_confidence,
        reason: parsed.reason
      }
    });

  } catch (error) {
    output.push({
      json: {
        success: false,
        error: error.message
      }
    });
  }
}

return output;

